versionC.grafica ? Plot.plot({
  width: Math.min(width, 760), height: 220, marginLeft: 110,
  x: {label: "Ahorro frente a no subastar [COP/kWh] →", grid: true},
  y: {label: null, domain: tablaC.mundos.filter((m, j) =&gt; !maquilladaC || j &lt; 2)},
  marks: [
    Plot.barX(versionC.grafica, {x: "valor", y: "mundo", fill: (d) =&gt; d.valor &gt;= 0 ? COLORES.verde : COLORES.rojo}),
    Plot.text(versionC.grafica, {x: (d) =&gt; Math.max(0, d.valor), y: "mundo", text: (d) =&gt; `${formatoNumero(0)(d.valor)}`, dx: 12}),
    Plot.ruleX([0]),
  ],
}) : html``









