  const nombres = ["la recomendación", "la razón", "el riesgo", "la señal de revisión"];
  const n = versionC.elementos.filter(Boolean).length;
  const cifras = (versionC.texto.match(/\d+(?:,\d+)?/g) ?? []).length + (versionC.tabla ? versionC.tabla.filas.flat().filter((c) =&gt; /\d/.test(c)).length : 0) + (versionC.grafica ? versionC.grafica.length : 0);
