  pasos = pasos === -1 ? serie.length - 1 : pasos - 1;
  const final = historia[pasos];
  const paso = Object.fromEntries(g.nodos.map((n) =&gt; [n, historia.findIndex((e) =&gt; e[n] === 1)]));
  const nodos = g.nodos.map((n) =&gt; ({id: n, x: COMERCIOS.posicion[n][0], y: COMERCIOS.posicion[n][1], activo: final[n] === 1,
    etiqueta: final[n] === 1 ? `${n} (${paso[n]})` : n}));
  const aristas = COMERCIOS.aristas.map(([a, b]) =&gt; ({x1: COMERCIOS.posicion[a][0], y1: COMERCIOS.posicion[a][1], x2: COMERCIOS.posicion[b][0], y2: COMERCIOS.posicion[b][1]}));
  return {nodos, aristas, fraccion: serie[pasos], pasos, adoptan: nodos.filter((d) =&gt; d.activo).length, serie: serie.slice(0, pasos + 1)};
}









