difusionB = {
  const N = 1000, P = 0.01, PASOS = 40, CORRIDAS = 20;
  const t = [...Array(PASOS + 1).keys()];
  const curvas = [...Array(CORRIDAS).keys()].map((s) =&gt; fracciones(grafoB
    ? bassEnRed(grafoB, P, qB, PASOS, {semilla: 1 + s})
    : bassEnRedCompleta(N, P, qB, PASOS, {semilla: 1 + s}), 1));
  const media = t.map((k) =&gt; curvas.reduce((a, c) =&gt; a + c[k], 0) / CORRIDAS);
  const ajuste = ajustarBass(t, media.map((x) =&gt; x * N));
  const curvaAjuste = bass(ajuste.p, ajuste.q, ajuste.m, t).map((f) =&gt; f.acumulado / N);
  const agregado = bassDiscreto(P, qB, 1, PASOS).map((f) =&gt; f.acumulado);
  const filas = t.flatMap((x, k) =&gt; [
    {t: x, valor: agregado[k], serie: "agregado con q individual"},
    {t: x, valor: media[k], serie: "promedio en la red"},
    {t: x, valor: curvaAjuste[k], serie: "Bass ajustado al promedio"}]);
  return {filas, ajuste, anio10: media[10], agrupamiento: grafoB ? agrupamientoMedio(grafoB) : 1};
}









