  const corteV = origenC === destinoC || adyacentes ? [] : corteMinimoVertices(g, [origenC], [destinoC]);
  const enCorte = new Set(corteA.map(([a, b]) =&gt; `${a}|${b}`));
  const aristas = stnC.aristas.map((e) =&gt; {
    const clave = String(e.a) &lt; String(e.b) ? `${e.a}|${e.b}` : `${e.b}|${e.a}`;
    return {...e, x1: posicion[e.a].lon, y1: posicion[e.a].lat, x2: posicion[e.b].lon, y2: posicion[e.b].lat, corte: enCorte.has(clave)};
  });
  const tramos = camino ? camino.slice(1).map((n, i) =&gt; ({x1: posicion[camino[i]].lon, y1: posicion[camino[i]].lat, x2: posicion[n].lon, y2: posicion[n].lat})) : [];
  const km = camino ? camino.slice(1).reduce((suma, n, i) =&gt; {
    const e = stnC.aristas.find((x) =&gt; (x.a === camino[i] && x.b === n) || (x.b === camino[i] && x.a === n));
    return suma + (e ? e.longitud_km : 0);
  }, 0) : 0;
  return {aristas, tramos, camino, corteA, corteV, adyacentes, km,
    nodos: stnC.nodos.map((n) =&gt; ({...n, enCorte: corteV.includes(n.id), extremo: n.id === origenC || n.id === destinoC}))};
}









