Ver el código en Python
votanteV = {
  const g = grafo(redesV[redV], [...Array(400).keys()]);
  const k = Object.fromEntries(g.nodos.map((n) =&gt; [n, grado(g, n)]));
  const suma = g.nodos.reduce((a, n) =&gt; a + k[n], 0);
  const cuantos = Math.round(fraccionV * 400);
  const orden = [...g.nodos].sort((a, b) =&gt; k[b] - k[a] || a - b);
  const corridas = [];
  let omegaMedio = 0;
  for (let c = 0; c &lt; 200; c++) {
    let favorables;
    if (dondeV === "hubs") favorables = new Set(orden.slice(0, cuantos));
    else {
      const u = azar(semillaCorrida(c, 9000)), resto = [...g.nodos];
      favorables = new Set();
      while (favorables.size &lt; cuantos) favorables.add(resto.splice(Math.floor(u() * resto.length), 1)[0]);
    }
    omegaMedio += [...favorables].reduce((a, n) =&gt; a + k[n], 0) / suma / 200;
    const iniciales = Object.fromEntries(g.nodos.map((n) =&gt; [n, favorables.has(n) ? 1 : 0]));
    const r = modeloVotante(g, {estadosIniciales: iniciales, barridos: 50000, semilla: semillaCorrida(c, 5000)});
    const aFavor = Object.values(r.historia[r.historia.length - 1]).every((v) =&gt; v === 1);
    corridas.push({barrido: r.barridoConsenso, desenlace: aFavor ? "consenso a favor" : "consenso en contra"});
  }
  const barridos = corridas.map((d) =&gt; d.barrido).sort((a, b) =&gt; a - b);
  return {corridas, omega: omegaMedio, probabilidad: corridas.filter((d) =&gt; d.desenlace === "consenso a favor").length / 200,
    mediana: (barridos[99] + barridos[100]) / 2, p10: barridos[19], p90: barridos[179]};
}









