Ver el código en Python
eulerI = {
  const tau = 4;
  const r = simular(ajustePrimerOrden({valor_inicial: 100, meta: 0, tau}), {tFinal: 40, paso: pasoI, metodo: "euler"});
  const puntos = r.tiempo.map((t, k) =&gt; ({t, P: r.variables.stock[k]})).filter((d) =&gt; d.t &lt;= 24 + 1e-9);
  const exacta = Array.from({length: 241}, (_, k) =&gt; ({t: k / 10, P: 100 * Math.exp(-(k / 10) / tau)}));
  const lectura = puntos.find((d) =&gt; d.t &gt;= 8 - 1e-9);
  const razon = pasoI / tau;
  const veredicto = razon &lt;= 0.25 ? "Paso fino: confirme partiéndolo antes de reportar"
    : razon &lt; 1 ? "Paso grueso: error apreciable"
    : razon === 1 ? "Vacía la cartera en un solo paso"
    : razon &lt; 2 ? "Cambia de signo: sin sentido físico"
    : razon === 2 ? "Oscila sin amortiguarse: artefacto numérico"
    : "Inestable: la oscilación crece";
  return {puntos, exacta, lectura, verdad: 100 * Math.exp(-lectura.t / tau), razon, veredicto};
}









